def _addresses(items) -> list:
    if items is None:
        return []
    if isinstance(items, (str, dict)):
        items = [items]
    return [{"email": a} if isinstance(a, str) else a for a in items]


def _clean(d: dict) -> dict:
    return {k: v for k, v in d.items() if v is not None}


