    async def __aenter__(self) -> AsyncAgentBox:
        return self

    async def __aexit__(self, *exc) -> None:
        await self.close()

    async def me(self) -> dict:
        return await self.request("GET", "/v1/me")

    async def request(
        self,
        method: str,
        path: str,
        *,
        params: dict | None = None,
        json: Any = None,
        idempotency_key: str | None = None,
        timeout: float | None = None,
    ) -> Any:
        headers = {}
        method = method.upper()
        if method == "POST" and (
            path == "/v1/inboxes" or path == "/v1/connections" or path.endswith(("/messages", "/reply", "/forward"))
        ):
            idempotency_key = idempotency_key or str(uuid.uuid4())
        if idempotency_key:
            headers["Idempotency-Key"] = idempotency_key
