    def __init__(self, client: AsyncAgentBox) -> None:
        self._c = client

    async def iter(self, *args, **kwargs):
        """Iterate every item, fetching subsequent pages lazily."""
        while True:
            page = await self.list(*args, **kwargs)
            if isinstance(page, list):
                for item in page:
                    yield item
                return
            for item in page["data"]:
                yield item
            if not page.get("next_cursor"):
                return
            kwargs["cursor"] = page["next_cursor"]


