class Attachments(_Resource):
    async def upload_file(self, path: str | Path, content_type: str | None = None) -> str:
        import mimetypes

        file = Path(path)
        return await self.upload(
            file.name,
            file.read_bytes(),
            content_type or mimetypes.guess_type(file.name)[0] or "application/octet-stream",
        )

    async def upload(self, filename: str, content: bytes, content_type: str = "application/octet-stream") -> str:
        """Create a pre-signed upload, PUT the bytes, return the attachment id to use in send/reply."""
        up = await self._c.request(
            "POST",
            "/v1/attachments/uploads",
            json={"filename": filename, "content_type": content_type, "size_bytes": len(content)},
        )
        async with httpx.AsyncClient(timeout=120.0) as ext:
            r = await ext.put(
                up["upload_url"], content=content, headers=up.get("headers") or {"Content-Type": content_type}
            )
            r.raise_for_status()
        return up["attachment_id"]

    async def get(self, attachment_id: str) -> dict:
        return await self._c.request("GET", f"/v1/attachments/{attachment_id}")

    async def list(self, message_id: str) -> dict:
        return await self._c.request("GET", f"/v1/messages/{message_id}/attachments")

    async def download_url(self, attachment_id: str) -> dict:
        return await self._c.request("GET", f"/v1/attachments/{attachment_id}/download")

    async def download(self, attachment_id: str) -> bytes:
        url = (await self.download_url(attachment_id))["url"]
        async with httpx.AsyncClient(timeout=120.0) as ext:
            r = await ext.get(url)
            r.raise_for_status()
            return r.content


